# PW03B common: PPSW-family coefficient construction (APNUM (3.2),(3.3); route 'tau-solve'), float64 + mpmath.
import numpy as np, mpmath as mp
P26 = dict(c=["-1.702","-0.51","-0.195797762","0.155193392","0.755672784","1"],
  g0=["0.214789562","0.249182503","0.237832565","0.245204742","0.353848357"],
  g1=["0.566334104","0.496228487","0.518584061","0.498857638","0.502412430"])
def gam_ppsw2(c, g0, g1, sg):   # APNUM (3.8) for i<s, (3.6) for i=s ; works for numpy and mpmath
    s=len(c); g=[g0[i]/(1+sg*g1[i]) for i in range(s-1)]
    g.append(1/(sg*sum(1/(1+sg-cj) for cj in c))); return g
def coeffs_np(c, g, sg):
    c=np.asarray(c,float); g=np.asarray(g,float); s=len(c); tau=(c-1)/sg
    Wt=np.vander(tau,s,increasing=True).T            # Wt[k,j]=tau_j^k
    Cp=np.array([c**k for k in range(s)])            # Cp[k,i]=c_i^k
    ThT=np.linalg.solve(Wt,Cp); Th=ThT.T
    A=g[:,None]*Th
    Dm=np.zeros((s,s))
    for k in range(1,s): Dm[k]=k*tau**(k-1)
    R2=Cp-Dm@A.T
    B=np.linalg.solve(Wt,R2).T
    return B,A,-A,Th
def coeffs_mp(c, g, sg):
    mp.mp.dps=mp.mp.dps; s=len(c); tau=[(cj-1)/sg for cj in c]
    Wt=mp.matrix(s,s); Cp=mp.matrix(s,s); Dm=mp.zeros(s,s)
    for k in range(s):
        for j in range(s):
            Wt[k,j]=tau[j]**k; Cp[k,j]=c[j]**k
            if k>=1: Dm[k,j]=k*tau[j]**(k-1)
    Wi=Wt**-1
    Th=(Wi*Cp).T
    A=mp.matrix(s,s)
    for i in range(s):
        for j in range(s): A[i,j]=g[i]*Th[i,j]
    B=(Wi*(Cp-Dm*A.T)).T
    return B,A
def quotient(B):
    s=B.shape[0]; S=np.eye(s); S[:,0]=1.0
    M=np.linalg.solve(S,B@S); return M[1:,1:], M[0,1:]
def alpha_deg(B,g,nphi=361,nr=300,rlo=-5,rhi=9):
    rs=np.logspace(rlo,rhi,nr); g=np.asarray(g,float)
    def f(p):
        z=rs*np.exp(1j*(np.pi-np.radians(p)))
        M=(1.0/(1.0-z[:,None]*g[None,:]))[:,:,None]*B[None,:,:]
        return float(np.max(np.abs(np.linalg.eigvals(M))))
    prev=0.0
    for p in np.linspace(0,90,nphi):
        if f(p)>=1-1e-12:
            lo,hi=prev,p
            for _ in range(40):
                m=0.5*(lo+hi)
                if f(m)>=1-1e-12: hi=m
                else: lo=m
            return lo
        prev=p
    return 90.0
# PW03B-1: NUMERICAL variable-step zero-stability checks for reconstructed PPSW2-6. NOT a proof.
import numpy as np, json, itertools, sys
c=np.array([float(x) for x in P26["c"]]); g0=np.array([float(x) for x in P26["g0"]]); g1=np.array([float(x) for x in P26["g1"]])
def Bof(sg): return coeffs_np(c, gam_ppsw2(c,g0,g1,sg), sg)[0]
out={}
# Z1 pointwise quotient spectral radius on fine grid
sg_grid=np.round(np.arange(0.05,1.6001,0.01),4)
rq=[]
for sg in sg_grid:
    Bq,_=quotient(Bof(sg)); rq.append(float(np.max(np.abs(np.linalg.eigvals(Bq)))))
rq=np.array(rq); out["Z1_pointwise_quotient_rho"]={"sigma":[float(x) for x in sg_grid[::5]],"rho":[round(float(x),5) for x in rq[::5]],
   "max_sigma_with_rho_lt_1_contiguous_from_1":None}
i1=int(np.argmin(abs(sg_grid-1.0))); j=i1
while j+1<len(rq) and rq[j+1]<1: j+=1
k=i1
while k-1>=0 and rq[k-1]<1: k-=1
out["Z1_pointwise_quotient_rho"]["max_sigma_with_rho_lt_1_contiguous_from_1"]=[float(sg_grid[k]),float(sg_grid[j])]
out["Z1_max_entry_|B|_at"]={str(s):float(np.max(abs(Bof(s)))) for s in [0.1,0.5,0.8,1.0,1.2,1.33,1.5]}
# Z2 random sequences on [sa,sb]
rng=np.random.default_rng(20261111)
def run(sa,sb,mode,M=20000):
    L=np.eye(6); worst=0.0
    for m in range(M):
        if mode=="uniform": sg=rng.uniform(sa,sb)
        elif mode=="vertex": sg=sa if rng.random()<0.5 else sb
        elif mode=="alt": sg=sa if m%2==0 else sb
        elif mode=="1:k": sg=sb if m%4==3 else sa   # 3 shrink 1 grow
        L=Bof(sg)@L; worst=max(worst,float(np.max(abs(L))))
    return worst
Z2={}
for sa in [0.1,0.5,0.8]:
    for sb in [1.0,1.1,1.2,1.3,1.5]:
        for mode in ["uniform","vertex","alt"]:
            Z2[f"[{sa},{sb}]_{mode}"]=run(sa,sb,mode,6000)
out["Z2_max_entry_of_product_6000_steps"]=Z2
# Z3 word search (quotient JSR lower bound / norm upper bound on FINITE alphabet)
def jsr_words(alpha_set,Lmax):
    Bq=[quotient(Bof(s))[0] for s in alpha_set]; res={}
    cur=[np.eye(5)]
    best_lb=0.0; ub={}
    for L in range(1,Lmax+1):
        nxt=[]
        for M in cur:
            for Bm in Bq: nxt.append(Bm@M)
        cur=nxt; arr=np.array(cur)
        lb=max(float(np.max(np.abs(np.linalg.eigvals(a))))**(1.0/L) for a in arr[::max(1,len(arr)//20000)])
        nb=float(np.max(np.linalg.norm(arr,2,axis=(1,2))))**(1.0/L)
        res[L]=dict(max_rho_word_pow=round(lb,5),max_norm_pow=round(nb,5),n_words=len(arr))
    return res
Z3={}
for sa,sb in [(0.8,1.2),(1/1.2,1.2),(0.5,1.2),(0.1,1.2),(0.8,1.1),(0.8,1.3),(0.9,1.5)]:
    al=sorted(set(np.round([sa,0.5*(sa+1),1.0,0.5*(1+sb),sb],6)))
    Z3[f"[{sa:.4f},{sb}]"]=dict(alphabet=al,words=jsr_words(al,7))
out["Z3_finite_alphabet_words"]=Z3
print(json.dumps(out,indent=1))

