# PW03B-2: reproduce OTHER parallel peer-W families from printed/derivable parameters (BIT 2005 mipeer s; SINUM 2004 PPSW1 6b/6c).
import numpy as np, json
from scipy.optimize import brentq
rho=lambda M: float(np.max(np.abs(np.linalg.eigvals(M))))
def cheb_nodes(s):  # BIT (5.8)
    i=np.arange(1,s+1); return np.cos((2*s+1-2*i)/(2*s)*np.pi)/np.cos(np.pi/(2*s))
def sup_root(s):    # BIT Remark 2.1: (s-2) x^(s-1) - (s-1) x^(s-2) - 1 = 0 in (0,2/(s-1))?? printed text; solve root >1 numerically
    f=lambda x:(s-2)*x**(s-1)-(s-1)*x**(s-2)-1
    xs=np.linspace(1.0001,3,30000); v=[f(x) for x in xs]
    for a,b,fa,fb in zip(xs[:-1],xs[1:],v[:-1],v[1:]):
        if fa*fb<0: return brentq(f,a,b)
def superconv_resid(c,gam):  # v.w with v left eigvec of B(1) (eig 1, v.1=1), w_i=phi(1+c_i)-gam_i phi'(1+c_i)   (BIT (4.5),(4.7))
    B,A,_,_=coeffs_np(c,gam,1.0)
    ev,V=np.linalg.eig(B.T); k=int(np.argmin(abs(ev-1))); v=np.real(V[:,k]); v=v/np.sum(v)
    ph=np.poly(c); dph=np.polyder(ph); x=1+c
    w=np.polyval(ph,x)-gam*np.polyval(dph,x)
    return float(v@w)
def analyse(name,c,gam,sig_list=(0.8,0.9,1.0,1.1,1.2,1.33,1.5)):
    c=np.asarray(c,float); gam=np.asarray(gam,float)
    B,_,_,_=coeffs_np(c,gam,1.0)
    r=dict(name=name,s=len(c),c=[float(x) for x in c],gamma=[float(x) for x in gam],gamma_min=float(gam.min()),
           alpha_deg_sigma1=round(alpha_deg(B,gam),3),abs_eig_B1=[round(float(x),6) for x in sorted(abs(np.linalg.eigvals(B)),reverse=True)],
           max_abs_B1=float(abs(B).max()),superconv_resid_sigma1=superconv_resid(c,gam))
    rq={}
    for sg in sig_list:
        Bs=coeffs_np(c,gam,sg)[0]; Bq=quotient(Bs)[0]; rq[str(sg)]=round(rho(Bq),5)
    r["quotient_rho_by_sigma"]=rq
    # oscillating pair (r,1/r) and general-pair worst on grid [0.5,smax]
    Bqf=lambda sg: quotient(coeffs_np(c,gam,sg)[0])[0]
    r["pair_(r,1/r)_rho_per_step"]={str(x):round(rho(Bqf(x)@Bqf(1/x))**0.5,5) for x in (1.1,1.2,1.3,1.33,1.4)}
    gr=np.round(np.arange(0.5,1.5001,0.025),4); M={float(x):Bqf(float(x)) for x in gr}
    wc={}
    for smax in (1.1,1.2,1.3,1.4):
        G=[x for x in M if x<=smax]; wmax=0
        for x in G:
            for y in G: wmax=max(wmax,rho(M[x]@M[y])**0.5)
        wc[str(smax)]=round(wmax,5)
    r["worst_pair_rho_per_step_on_[0.5,smax]"]=wc
    return r
out={}
# --- BIT mipeer s, s=3,4,5 reproduce Table 7.1; s=6 reconstruct
tab71={3:(0.5858,0.9057,90.0),4:(0.4039,0.5443,90.0),5:(0.3075,0.3756,89.8)}
for s in (3,4,5,6):
    c=cheb_nodes(s); sup=sup_root(s); g1=1-1/sup
    gm=lambda g0: g0+g1*c
    gs=np.linspace(g1*1.0001+1e-6,3.0,3000)   # (2.18): g0 > -g1 min c = g1
    vals=[superconv_resid(c,gm(g)) for g in gs]; roots=[]
    for a,b,fa,fb in zip(gs[:-1],gs[1:],vals[:-1],vals[1:]):
        if fa*fb<0: roots.append(brentq(lambda g:superconv_resid(c,gm(g)),a,b,xtol=1e-14))
    rec=dict(s=s,sigma_sup=sup,g1_from_Remark2_1=g1,g0_roots_superconv=roots,table71=tab71.get(s),c_cheb=[float(x) for x in c])
    if roots: rec["analysis_first_root"]=analyse(f"mipeer{s}(g0=root0)",c,gm(roots[0]))
    out[f"mipeer{s}"]=rec
# also BIT-table-71 printed (rounded) values for s=3,4,5 for direct comparison
for s,(g1p,g0p,al) in tab71.items():
    c=cheb_nodes(s); out[f"mipeer{s}_printed_g0g1"]=analyse(f"mipeer{s}_printed",c,g0p+g1p*c)
# --- SINUM 2004 PPSW1 (single gamma): Table 1 gammas, Table 2 knots
sin={"5b":([-1,-0.5,0,0.5,1],0.722499,79.6),"6b":([-1,-0.5,0,0.4,0.8,1],0.619411,57.5),"6c":([-1,-0.5,0,0.4,0.8,1],1.087080,87.9),
     "4b":([-1,-0.3,0.7,1],0.912763,89.9),"7c":([-1,-0.7,-0.2,0,0.2,0.6,1],0.885444,81.3)}
for k,(c,g,al) in sin.items():
